[tool: web_search] {
  "results": [
    {
      "title": "Influenza vaccines: WHO position paper, May 2024",
      "url": "https://www.who.int/publications/i/item/whi-2024-influenza-vaccines-position-paper",
      "snippet": "WHO\u2019s 2024 position paper recommends annual influenza vaccination for older adults, including people aged 65 years and older, as a priority group for seasonal vaccination. The paper summarizes evidence that influenza causes substantial morbidity and mortality in older adults and notes that vaccine effectiveness varies by season and vaccine match.",
      "domain": "who.int",
      "rank": 1
    },
    {
      "title": "WHO recommendations on seasonal influenza vaccination for older adults",
      "url": "https://www.who.int/news-room/questions-and-answers/item/seasonal-influenza-vaccination-older-adults",
      "snippet": "WHO says adults 65 years and older should be prioritized for seasonal influenza vaccination because age-related immune decline increases the risk of severe disease, hospitalization, and death. The guidance cites the use of inactivated influenza vaccines and highlights that vaccination is most effective when administered before influenza activity increases each year.",
      "domain": "who.int",
      "rank": 2
    },
    {
      "title": "Vaccines against influenza: WHO position and priorities for older persons",
      "url": "https://www.who.int/immunization/policy/position_papers/influenza/en/",
      "snippet": "In its influenza vaccine position paper, WHO identifies older persons as a high-risk group for whom annual vaccination is recommended, alongside pregnant women, young children, and people with chronic conditions. WHO notes that seasonal influenza epidemics cause an estimated 290,000 to 650,000 respiratory deaths worldwide each year.",
      "domain": "who.int",
      "rank": 3
    },
    {
      "title": "Seasonal influenza vaccination: WHO guidance for countries",
      "url": "https://www.who.int/teams/immunization-vaccines-and-biologicals/diseases/influenza/seasonal-influenza-vaccination",
      "snippet": "WHO guidance on seasonal influenza vaccination includes adults 65 years and older among the first groups to be considered for immunization programs, especially where vaccine supply is limited. The guidance explains that countries should set priority groups based on local epidemiology, age structure, and health-system capacity.",
      "domain": "who.int",
      "rank": 4
    },
    {
      "title": "Influenza and older adults: WHO facts and recommendations",
      "url": "https://www.who.int/health-topics/influenza/older-adults",
      "snippet": "WHO states that people aged 65 and over are more likely to develop serious influenza complications, including pneumonia and exacerbations of chronic heart and lung disease. Annual vaccination is recommended because circulating influenza viruses change from season to season and protection can wane over time.",
      "domain": "who.int",
      "rank": 5
    }
  ],
  "query": "current WHO influenza vaccine recommendations adults 65 years and older site:who.int",
  "count": 5
}

