[tool: web_search] {
  "results": [
    {
      "title": "Effectiveness of influenza vaccine in adults aged 65 years and older during the 2023-2024 season",
      "url": "https://pubmed.ncbi.nlm.nih.gov/38745129/",
      "snippet": "PubMed record for a 2024 peer-reviewed study reporting vaccine effectiveness estimates in adults aged 65 years and older during the 2023-2024 influenza season. The analysis included laboratory-confirmed influenza outcomes and found moderate protection against medically attended illness, with higher effectiveness against hospitalization than against outpatient visits.",
      "domain": "pubmed.ncbi.nlm.nih.gov",
      "rank": 1
    },
    {
      "title": "Influenza vaccine effectiveness against hospitalization among adults aged 65 years and older: multicenter study, 2024",
      "url": "https://pubmed.ncbi.nlm.nih.gov/38690214/",
      "snippet": "This 2024 PubMed-indexed article evaluates influenza vaccine effectiveness in older adults, focusing on severe outcomes in patients 65 years and older. The study reports site-specific estimates from multiple hospitals and includes adjusted effectiveness calculations for vaccine products used in the 2023-2024 season.",
      "domain": "pubmed.ncbi.nlm.nih.gov",
      "rank": 2
    },
    {
      "title": "Seasonal influenza vaccine effectiveness in older adults: a systematic review and meta-analysis, 2024",
      "url": "https://pubmed.ncbi.nlm.nih.gov/38577420/",
      "snippet": "PubMed listing for a 2024 systematic review that pooled evidence from randomized and observational studies in adults aged 65+ years. The review compares vaccine effectiveness across seasons and notes that protection varied by strain, with the strongest estimates generally seen for influenza A(H1N1)pdm09.",
      "domain": "pubmed.ncbi.nlm.nih.gov",
      "rank": 3
    },
    {
      "title": "High-dose versus standard-dose influenza vaccine effectiveness in adults 65 years and older, 2024",
      "url": "https://pubmed.ncbi.nlm.nih.gov/38811407/",
      "snippet": "A 2024 peer-reviewed comparative effectiveness study indexed in PubMed examining high-dose and standard-dose influenza vaccines in adults aged 65 years and older. The paper reports thousands of Medicare-linked encounters and analyzes laboratory-confirmed influenza plus influenza-related hospitalization within the same season.",
      "domain": "pubmed.ncbi.nlm.nih.gov",
      "rank": 4
    },
    {
      "title": "Influenza vaccination and outcomes in community-dwelling older adults: evidence from the 2024 season",
      "url": "https://pubmed.ncbi.nlm.nih.gov/38499061/",
      "snippet": "PubMed result for a 2024 study of community-dwelling adults aged 65 years and older, using test-negative design methods to estimate vaccine effectiveness. The article includes age-stratified results, with separate analyses for ages 65-74, 75-84, and 85+ years, and discusses waning protection later in the season.",
      "domain": "pubmed.ncbi.nlm.nih.gov",
      "rank": 5
    }
  ],
  "query": "peer-reviewed study influenza vaccine effectiveness older adults adults 65 years peer reviewed 2024 site:pubmed.ncbi.nlm.nih.gov",
  "count": 5
}

