[tool: web_search] {
  "results": [
    {
      "title": "Vaccines against influenza: WHO position paper \u2013 November 2024",
      "url": "https://www.who.int/publications/i/item/who-wer-2024-50-xxx",
      "snippet": "WHO updated its position paper on influenza vaccines in November 2024, noting that adults aged 65 years and older remain at higher risk of severe influenza outcomes and may benefit from age-appropriate vaccination strategies. The document summarizes WHO guidance on annual influenza vaccination and references vaccine formulations used in older adults, including higher-dose and adjuvanted products.",
      "domain": "who.int",
      "rank": 1
    },
    {
      "title": "Influenza vaccines and older adults: WHO recommendations for 2024",
      "url": "https://www.who.int/news-room/fact-sheets/detail/influenza-(seasonal)-vaccines",
      "snippet": "WHO states that annual influenza vaccination is recommended for people at higher risk of severe disease, including adults 65 years and older, especially in seasons with substantial circulation of influenza A(H1N1)pdm09 and A(H3N2). The guidance highlights that vaccine effectiveness varies by season, age, and vaccine type, and that protection is strongest when vaccination occurs before the winter season.",
      "domain": "who.int",
      "rank": 2
    },
    {
      "title": "Weekly Epidemiological Record: Influenza vaccines \u2013 WHO position paper",
      "url": "https://www.who.int/wer/2024/wer9950/en/",
      "snippet": "In the Weekly Epidemiological Record, WHO reviews evidence on influenza vaccination and notes that older adults, particularly those 65+, experience higher hospitalization and death rates from seasonal influenza. The paper describes the use of inactivated influenza vaccines, including standard-dose, adjuvanted, and high-dose formulations, as part of national programs.",
      "domain": "who.int",
      "rank": 3
    },
    {
      "title": "Seasonal influenza vaccination: key points for adults 65 years and older",
      "url": "https://www.who.int/teams/global-tuberculosis-programme/influenza-vaccination-older-adults",
      "snippet": "WHO recommends yearly influenza vaccination for older adults because immune response declines with age and chronic conditions such as heart disease, diabetes, and COPD increase complication risk. The page cites WHO guidance that vaccines should ideally be given before the onset of influenza season, with protection typically developing about 2 weeks after vaccination.",
      "domain": "who.int",
      "rank": 4
    },
    {
      "title": "Influenza vaccines: recommendations by age group",
      "url": "https://www.who.int/publications/i/item/influenza-vaccines-recommendations-age-groups-2024",
      "snippet": "WHO\u2019s 2024 influenza vaccine guidance includes adults aged 65 years and older among priority groups for seasonal vaccination, alongside pregnant women, healthcare workers, and people with chronic medical conditions. The recommendations discuss vaccine strain selection and note that annual updates are based on global surveillance data from the previous season.",
      "domain": "who.int",
      "rank": 5
    }
  ],
  "query": "WHO flu vaccine recommendations adults 65 years and older 2024 site:who.int",
  "count": 5
}

