[tool: web_search] {
  "results": [
    {
      "title": "WHO recommends annual influenza vaccination for older adults and people at higher risk",
      "url": "https://www.who.int/news-room/questions-and-answers/item/influenza-vaccination",
      "snippet": "WHO says influenza vaccination is recommended every year for pregnant women, children aged 6 months to 5 years, older adults, people with chronic medical conditions, and health workers. The organization notes that vaccine composition is updated annually and that protection can wane over time, which is why yearly vaccination is advised.",
      "domain": "who.int",
      "rank": 1
    },
    {
      "title": "Influenza vaccines: WHO position paper \u2013 November 2024",
      "url": "https://www.who.int/publications/i/item/who-wer-2024-xx",
      "snippet": "In its 2024 position paper, WHO reiterates that annual vaccination is recommended for older adults, pregnant women, health workers, and people with certain chronic conditions. The guidance references seasonal influenza vaccines and explains that the WHO vaccine composition recommendations are issued twice a year for the northern and southern hemispheres.",
      "domain": "who.int",
      "rank": 2
    },
    {
      "title": "Seasonal influenza: vaccination of older adults \u2013 WHO guidance",
      "url": "https://www.who.int/teams/immunization-vaccines-and-biologicals/diseases/influenza",
      "snippet": "WHO\u2019s influenza pages state that adults 65 years and older are among the groups at highest risk of severe influenza and complications. The agency recommends annual vaccination and emphasizes that timing should align with local influenza season, typically before virus circulation increases.",
      "domain": "who.int",
      "rank": 3
    },
    {
      "title": "Influenza (seasonal) fact sheet",
      "url": "https://www.who.int/news-room/fact-sheets/detail/influenza-(seasonal)",
      "snippet": "WHO estimates seasonal influenza causes 3\u20135 million cases of severe illness and up to 650,000 respiratory deaths each year worldwide. The fact sheet says vaccination is the most effective way to prevent severe disease and that older adults are a priority group for annual vaccination.",
      "domain": "who.int",
      "rank": 4
    },
    {
      "title": "WHO vaccine recommendations for 2024\u20132025 influenza season",
      "url": "https://www.who.int/news/item/2024-02-xx/who-recommends-composition-of-influenza-virus-vaccines-for-use-in-the-2024-2025-northern-hemisphere-influenza-season",
      "snippet": "WHO publishes twice-yearly recommendations on the composition of seasonal influenza vaccines; for 2024\u20132025, the northern hemisphere update was issued in February 2024. The guidance supports annual vaccination in adults 65 years and older because influenza viruses change and vaccine strains are updated each season.",
      "domain": "who.int",
      "rank": 5
    }
  ],
  "query": "site:who.int influenza vaccination adults 65 years older annual vaccination recommendation 2024 WHO",
  "count": 5
}

