[tool: web_search] {
  "results": [
    {
      "title": "Flu and People 65 Years and Older",
      "url": "https://www.cdc.gov/flu/highrisk/65over.htm",
      "snippet": "Adults 65 years and older are at higher risk of developing serious flu complications, and CDC recommends they get a flu vaccine every season. For the 2024-2025 season, CDC says people in this age group should receive a higher-dose or adjuvanted flu vaccine if available, including Fluzone High-Dose, Flublok, or Fluad.",
      "domain": "cdc.gov",
      "rank": 1
    },
    {
      "title": "Seasonal Influenza Vaccine Effectiveness, 2024-2025",
      "url": "https://www.cdc.gov/flu/vaccine-effectiveness/index.htm",
      "snippet": "CDC tracks seasonal flu vaccine effectiveness each year and notes that vaccination remains the best way to reduce the risk of flu and serious illness. The agency recommends annual vaccination for everyone 6 months and older, with special emphasis on adults age 65+ because they are more likely to be hospitalized with flu complications.",
      "domain": "cdc.gov",
      "rank": 2
    },
    {
      "title": "What Flu Vaccine Should People 65 Years and Older Get?",
      "url": "https://www.cdc.gov/flu/prevent/whoshouldvax.htm",
      "snippet": "CDC guidance says adults 65 and older should preferentially receive a higher-dose, recombinant, or adjuvanted influenza vaccine rather than standard-dose quadrivalent shots. These options include Fluzone High-Dose, Flublok, and Fluad, which are designed to produce a stronger immune response in older adults.",
      "domain": "cdc.gov",
      "rank": 3
    },
    {
      "title": "Flu and Older Adults: Questions and Answers",
      "url": "https://www.cdc.gov/flu/season/qa-flu-vaccine-older-adults.htm",
      "snippet": "Older adults are at increased risk for flu-related hospitalization and death, especially those 65 and older. CDC explains that flu vaccination can lower the risk of medical visits and severe outcomes, and recommends getting vaccinated in September or October when possible.",
      "domain": "cdc.gov",
      "rank": 4
    },
    {
      "title": "Getting a Flu Vaccine at Age 65 and Older",
      "url": "https://www.cdc.gov/flu/prevent/vaccine-selection.htm",
      "snippet": "CDC says there is no preference for one flu vaccine over another for most adults, but people age 65+ are an exception because higher-dose and adjuvanted options may provide better protection. The agency advises that if none of the preferred products are available, adults 65 and older should still get vaccinated with any age-appropriate influenza vaccine.",
      "domain": "cdc.gov",
      "rank": 5
    }
  ],
  "query": "CDC flu vaccine guidance adults 65 and older 2024 site:cdc.gov",
  "count": 5
}

