[tool: web_search] {
  "results": [
    {
      "title": "WHO recommends updated seasonal influenza vaccines for older adults in 2024\u20132025",
      "url": "https://www.who.int/news/item/2024-09-15/who-recommends-updated-seasonal-influenza-vaccines-for-older-adults",
      "snippet": "WHO\u2019s 2024 guidance says adults aged 65 years and older should receive an age-appropriate seasonal influenza vaccine every year, ideally before local flu circulation begins. The organization notes that high-dose or adjuvanted influenza vaccines may offer improved protection in older adults, who are at higher risk of severe disease and hospitalization.",
      "domain": "who.int",
      "rank": 1
    },
    {
      "title": "CDC: Flu vaccination for older adults aged 65 years and older",
      "url": "https://www.cdc.gov/flu/highrisk/65over.htm",
      "snippet": "The CDC recommends that everyone 6 months and older get a flu vaccine every season, with special emphasis on adults 65 years and older because they are at increased risk of complications. For the 2024\u20132025 season, CDC says older adults may benefit from high-dose, adjuvanted, or recombinant flu vaccines, which have shown better immune response in this age group.",
      "domain": "cdc.gov",
      "rank": 2
    },
    {
      "title": "WHO position paper on influenza vaccines",
      "url": "https://www.who.int/publications/i/item/who-wer9940-456-488",
      "snippet": "In its Weekly Epidemiological Record, WHO states that annual influenza vaccination is the most effective measure for preventing influenza and reducing severe outcomes in high-risk groups. The paper highlights adults 65 years and older, pregnant women, young children, and people with chronic conditions as priority groups for seasonal vaccination.",
      "domain": "who.int",
      "rank": 3
    },
    {
      "title": "Flu and older adults: why the annual shot matters after 65",
      "url": "https://www.health.harvard.edu/blog/flu-and-older-adults-why-the-annual-shot-matters-after-65-20240910",
      "snippet": "Older adults account for the majority of influenza-related hospitalizations and deaths in the United States, with risk rising sharply after age 65. Experts quoted in the article note that flu vaccines are updated annually to match circulating strains, and that high-dose formulations have been studied in people 65 and older.",
      "domain": "health.harvard.edu",
      "rank": 4
    },
    {
      "title": "Influenza vaccine recommendations for adults 65+ by WHO and national programs",
      "url": "https://www.immunize.org/ask-experts/topic/influenza/older-adults/",
      "snippet": "Immunize.org summarizes current recommendations that adults 65 years and older receive an influenza vaccine every year, with preference for enhanced formulations when available. The page cites studies showing high-dose quadrivalent influenza vaccine can produce stronger antibody responses than standard-dose vaccine in older adults.",
      "domain": "immunize.org",
      "rank": 5
    }
  ],
  "query": "current WHO flu vaccine recommendations older adults 65 annual influenza vaccine",
