[tool: web_search] {
  "results": [
    {
      "title": "statistics \u2014 Mathematical functions for Python 3.12.0 documentation",
      "url": "https://docs.python.org/3/library/statistics.html",
      "snippet": "Python\u2019s `statistics.pstdev()` returns the population standard deviation of data, dividing by `n` rather than `n-1`. The docs note that `statistics.pvariance()` is the corresponding population variance function, and both were added in Python 3.4.",
      "domain": "docs.python.org",
      "rank": 1
    },
    {
      "title": "Python statistics module: pstdev() and pvariance()",
      "url": "https://realpython.com/python-statistics/",
      "snippet": "In Python, `pstdev()` computes the square root of the population variance, making it the right choice when your data represents the entire population. Real Python\u2019s examples show how `stdev()` uses sample standard deviation with Bessel\u2019s correction (`n-1`), while `pstdev()` uses `n`.",
      "domain": "realpython.com",
      "rank": 2
    },
    {
      "title": "Coefficient of Variation in Python with statistics.pstdev()",
      "url": "https://datagy.io/coefficient-of-variation-python/",
      "snippet": "The coefficient of variation is calculated as `standard deviation / mean`, often multiplied by 100 to express a percentage. If you\u2019re using population data in Python, the formula becomes `statistics.pstdev(data) / statistics.mean(data) * 100`.",
      "domain": "datagy.io",
      "rank": 3
    },
    {
      "title": "Population Standard Deviation Formula and Examples",
      "url": "https://www.statology.org/population-standard-deviation/",
      "snippet": "Population standard deviation is defined as the square root of the average squared deviations from the population mean: `\u03c3 = \u221a(\u03a3(xi \u2212 \u03bc)\u00b2 / N)`. Statology\u2019s examples typically contrast this with sample standard deviation, which divides by `N - 1` instead of `N`.",
      "domain": "statology.org",
      "rank": 4
    },
    {
      "title": "Understanding Coefficient of Variation (CV)",
      "url": "https://www.investopedia.com/terms/c/coefficientofvariation.asp",
      "snippet": "The coefficient of variation (CV) measures relative dispersion and is calculated by dividing the standard deviation by the mean. For example, if a data set has a mean of 50 and a standard deviation of 5, the CV is 0.10, or 10%.",
      "domain": "investopedia.com",
      "rank": 5
    }
  ],
  "query": "Python statistics pstdev coefficient of variation formula population standard deviation",
  "count": 5
}

